import { useFetch } from '@cetus/hooks'
import { Token } from '@cetus/types'
import { useEffect, useState } from 'react'

/**
 * token 风险提示检查
 * @returns
 */
export default function useCheckTokenScamsAlert(coinInfo?: Token) {
  const [isScamsCoin, setIsScamsCoin] = useState<boolean | undefined>()
  const { fetchByApi } = useFetch()

  const checkIsScamsCoin = async (coinInfo: Token) => {
    const is_verified = coinInfo.is_verified === undefined ? coinInfo.is_trusted : coinInfo.is_verified
    if (is_verified) {
      return false
    }

    try {
      let isScamsCoin = false
      const { coins } = await fetchByApi(`/router_v2/honey_pot_check?coins=${coinInfo?.coin_type}`, 'GET')
      console.log('🚀🚀🚀 ~ useCheckTokenScamsAlert.ts:23 ~ checkIsScamsCoin ~ coins:', coins)
      if (coins && coins.length > 0) {
        isScamsCoin = coins[0]?.is_honey_pot_scam
      }

      return isScamsCoin
    } catch (error) {
      console.log('🚀 ~ file: useCheckTokenScamsAlert.ts:19 ~ checkTokenScams ~ error:', error)
    }

    return false
  }

  useEffect(() => {
    setIsScamsCoin(undefined)
    if (coinInfo) {
      checkIsScamsCoin(coinInfo).then(res => {
        setIsScamsCoin(res)
      })
    }
  }, [coinInfo?.coin_type])

  return {
    isScamsCoin
  }
}
